function getStreak(habit) {
  let count = 0
  const cursor = new Date()
  for (let i = 0; i < 365; i++) {
    const date = dateKey(cursor)
    const kept = habit.type === 'bad'
      ? date >= (habit.stoppedAt || habit.createdAt) && habit.history?.[date] !== false
      : !!habit.history?.[date]
    if (!kept) break
    count++
    cursor.setDate(cursor.getDate() - 1)
  }
  return count
}

function App() {
  const localSeed = useRef({ habits: stored('steady-habits', []), expenses: stored('levelup-expenses', []), todos: stored('levelup-todos', []), todoCategories: stored('levelup-todo-categories', []), paymentModes: stored('levelup-payment-modes', []), bodyWeights: stored('levelup-body-weights', []), plans: stored('levelup-wellness-plans', { diet: null, workout: null, schedule: null }), todoPrefs: applyTodoDefault(stored('levelup-todo-prefs', null)) })
  const cloudPrefsInitialized = useRef(false)
  const [habits, setHabits] = useState(() => localSeed.current.habits)
  const [expenses, setExpenses] = useState(() => localSeed.current.expenses)
  const [todos, setTodos] = useState(() => localSeed.current.todos)
  const [todoCategories, setTodoCategories] = useState(() => localSeed.current.todoCategories)
  const [bodyWeights, setBodyWeights] = useState(() => localSeed.current.bodyWeights)
  const [plans, setPlans] = useState(() => localSeed.current.plans)
  const [todoPrefs, setTodoPrefs] = useState(() => localSeed.current.todoPrefs)
  const [todoEditor, setTodoEditor] = useState(null)
  const [todoConfirm, setTodoConfirm] = useState(null)
  const [toast, setToast] = useState('')
  const [paymentModes, setPaymentModes] = useState(() => Array.from(new Set([...defaultPaymentModes, ...localSeed.current.paymentModes])))
  const [expenseForm, setExpenseForm] = useState({ description: '', amount: '', paymentMode: '', date: today })
  const [editingExpense, setEditingExpense] = useState(null)
  const [bulkExpenses, setBulkExpenses] = useState([])
  const [expenseMonth, setExpenseMonth] = useState('all')
  const [expenseYear, setExpenseYear] = useState('all')
  const [expenseStart, setExpenseStart] = useState('')
  const [expenseEnd, setExpenseEnd] = useState('')
  const [page, setPageState] = useState(() => window.history.state?.levelupPage || 'dashboard')
  const [filter, setFilter] = useState('all')
  const [editing, setEditing] = useState(null)
  const [menuOpen, setMenuOpen] = useState(null)
  const [form, setForm] = useState({ name: '', note: '', target: '', type: 'good', color: '#4fa3ff', startedAt: today, stoppedAt: today })
  const [mobileNavOpen, setMobileNavOpen] = useState(false)
  const [user, setUser] = useState(null)
  const [cloudLoaded, setCloudLoaded] = useState(!firebaseReady)
  const [authChecked, setAuthChecked] = useState(!firebaseReady)
  const [authError, setAuthError] = useState('')
  const firstName = user?.displayName?.trim().split(/\s+/)[0]
  const appName = firstName ? `${firstName} Level Up` : 'LevelUp'
  const setPage = destination => {
    if (destination === page) return
    window.history.pushState({ ...window.history.state, levelupPage: destination }, '', window.location.href)
    setPageState(destination)
  }

  useEffect(() => localStorage.setItem('steady-habits', JSON.stringify(habits)), [habits])
  useEffect(() => localStorage.setItem('levelup-expenses', JSON.stringify(expenses)), [expenses])
  useEffect(() => localStorage.setItem('levelup-todos', JSON.stringify(todos)), [todos])
  useEffect(() => localStorage.setItem('levelup-todo-categories', JSON.stringify(todoCategories)), [todoCategories])
  useEffect(() => localStorage.setItem('levelup-body-weights', JSON.stringify(bodyWeights)), [bodyWeights])
  useEffect(() => { try { localStorage.setItem('levelup-wellness-plans', JSON.stringify(plans)) } catch { setToast('PDF is too large to save in this browser') } }, [plans])
  useEffect(() => localStorage.setItem('levelup-todo-prefs', JSON.stringify(todoPrefs)), [todoPrefs])
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 2600); return () => clearTimeout(timer) }, [toast])
  useEffect(() => localStorage.setItem('levelup-payment-modes', JSON.stringify(paymentModes)), [paymentModes])
  useEffect(() => { window.scrollTo(0, 0) }, [page])
  useEffect(() => {
    if (!window.history.state?.levelupPage) window.history.replaceState({ ...window.history.state, levelupPage: page }, '', window.location.href)
    const goBack = event => {
      setPageState(event.state?.levelupPage || 'dashboard')
      setMobileNavOpen(false)
      setTodoEditor(null)
      setTodoConfirm(null)
    }
    window.addEventListener('popstate', goBack)
    return () => window.removeEventListener('popstate', goBack)
  }, [])
  useEffect(() => {
    if (!menuOpen) return
    const closeMenu = event => { if (!event.target.closest('.card-actions')) setMenuOpen(null) }
    document.addEventListener('pointerdown', closeMenu)
    return () => document.removeEventListener('pointerdown', closeMenu)
  }, [menuOpen])
  useEffect(() => {
    if (!mobileNavOpen) return
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = previousOverflow }
  }, [mobileNavOpen])
  useEffect(() => {
    if (!firebaseReady) return
    return onAuthStateChanged(auth, currentUser => {
      setUser(currentUser)
      setCloudLoaded(!currentUser)
      setAuthChecked(true)
      setAuthError('')
    })
  }, [])
  useEffect(() => {
    if (!user) { cloudPrefsInitialized.current = false; return }
    const habitsRef = doc(db, 'users', user.uid, 'habits', 'data')
    return onSnapshot(habitsRef, snapshot => {
      if (snapshot.exists()) {
        const data = snapshot.data()
        const cloudIsEmpty = !(data.items?.length || data.expenses?.length || data.todos?.length || data.todoCategories?.length || data.bodyWeights?.length || Object.values(data.plans || {}).some(Boolean))
        const localHasData = localSeed.current.habits.length || localSeed.current.expenses.length || localSeed.current.todos.length || localSeed.current.todoCategories.length || localSeed.current.bodyWeights.length || Object.values(localSeed.current.plans).some(Boolean)
        if (cloudIsEmpty && localHasData) setDoc(habitsRef, { items: localSeed.current.habits, expenses: localSeed.current.expenses, paymentModes: data.paymentModes || defaultPaymentModes, todos: localSeed.current.todos, todoCategories: localSeed.current.todoCategories, todoPrefs: localSeed.current.todoPrefs, bodyWeights: localSeed.current.bodyWeights, plans: localSeed.current.plans })
        else {
          // Keep a browser copy as a safety net when an older deployment has a
          // partial Firestore document. The next sync writes the merged record back.
          const mergedHabits = mergeSavedItems(localSeed.current.habits, data.items || [])
          const mergedExpenses = mergeSavedItems(localSeed.current.expenses, data.expenses || []).filter(expense => !isLegacyPresetExpense(expense))
          const mergedTodos = mergeSavedItems(localSeed.current.todos, data.todos || [])
          const mergedModes = Array.from(new Set([...defaultPaymentModes, ...localSeed.current.paymentModes, ...(data.paymentModes || [])]))
          const mergedCategories = [...new Set([...localSeed.current.todoCategories, ...data.todoCategories || [], ...mergedTodos.map(task => task.category).filter(Boolean)])].sort((a, b) => a.localeCompare(b))
          const mergedWeights = mergeSavedItems(localSeed.current.bodyWeights, data.bodyWeights || [])
          const mergedPlans = { ...data.plans, ...Object.fromEntries(Object.entries(localSeed.current.plans).filter(([, plan]) => plan)) }
          const mergedPrefs = applyTodoDefault(data.todoPrefs)
          setHabits(current => keepIfUnchanged(current, mergedHabits))
          setExpenses(current => keepIfUnchanged(current, mergedExpenses))
          setPaymentModes(current => keepIfUnchanged(current, mergedModes))
          setTodos(current => keepIfUnchanged(current, mergedTodos))
          setTodoCategories(current => keepIfUnchanged(current, mergedCategories))
          setBodyWeights(current => keepIfUnchanged(current, mergedWeights))
          setPlans(current => keepIfUnchanged(current, mergedPlans))
          if (!cloudPrefsInitialized.current) {
            setTodoPrefs(current => keepIfUnchanged(current, mergedPrefs))
            cloudPrefsInitialized.current = true
          }
        }
      } else setDoc(habitsRef, { items: localSeed.current.habits, expenses: localSeed.current.expenses, paymentModes: defaultPaymentModes, todos: localSeed.current.todos, todoCategories: localSeed.current.todoCategories, todoPrefs: localSeed.current.todoPrefs, bodyWeights: localSeed.current.bodyWeights, plans: localSeed.current.plans })
      setCloudLoaded(true)
    }, () => { setAuthError('Could not connect to your cloud habits.'); setCloudLoaded(true) })
  }, [user])
  useEffect(() => {
    if (!user || !cloudLoaded) return
    setDoc(doc(db, 'users', user.uid, 'habits', 'data'), { items: habits, expenses, paymentModes, todos, todoCategories, todoPrefs, bodyWeights, plans }).catch(() => setAuthError('Your latest change could not be synced.'))
  }, [habits, expenses, paymentModes, todos, todoCategories, todoPrefs, bodyWeights, plans, user, cloudLoaded])

  const stats = useMemo(() => {
    const done = habits.filter(h => h.type === 'bad' ? h.history?.[today] !== false : today >= (h.startedAt || h.createdAt) && h.history?.[today]).length
    const best = Math.max(0, ...habits.map(getStreak))
    return { done, total: habits.length, best }
  }, [habits])

  const goAdd = () => { setEditing(null); setForm({ name: '', note: '', target: '', type: 'good', color: '#4fa3ff', startedAt: today, stoppedAt: today }); setPage('add') }
  const goEdit = (habit) => { setEditing(habit.id); setForm({ name: habit.name, note: habit.note, target: habit.target || '', type: habit.type, color: habit.color, startedAt: habit.startedAt || habit.createdAt, stoppedAt: habit.stoppedAt || habit.createdAt }); setMenuOpen(null); setPage('add') }
  const toggleDate = (id, date = today) => setHabits(items => items.map(h => {
    if (h.id !== id) return h
    const completed = h.type === 'bad' ? date >= (h.stoppedAt || h.createdAt) && h.history?.[date] !== false : date >= (h.startedAt || h.createdAt) && !!h.history?.[date]
    return { ...h, history: { ...h.history, [date]: !completed } }
  }))
  const toggle = (id) => toggleDate(id)
  const deleteHabit = (id) => { setHabits(items => items.filter(h => h.id !== id)); setMenuOpen(null) }
  const save = (e) => {
    e.preventDefault()
    if (!form.name.trim()) return
    if (editing) setHabits(items => items.map(h => h.id === editing ? { ...h, ...form } : h))
    else setHabits(items => [...items, { ...form, id: Date.now(), history: {}, createdAt: today }])
    setPage('habits')
  }
  const shownHabits = habits.filter(h => filter === 'all' || h.type === filter)
  const expenseMonths = [...new Set(expenses.map(item => item.date.slice(0, 7)))].sort().reverse()
  const expenseYears = [...new Set(expenses.map(item => item.date.slice(0, 4)))].sort().reverse()
  const filteredExpenses = expenses.filter(item => (expenseMonth === 'all' || item.date.startsWith(expenseMonth)) && (expenseYear === 'all' || item.date.startsWith(expenseYear)) && (!expenseStart || item.date >= expenseStart) && (!expenseEnd || item.date <= expenseEnd))
  const deleteFilteredExpenses = () => {
    if (!filteredExpenses.length) return
    const scope = expenseMonth !== 'all' ? expenseMonth : expenseYear !== 'all' ? expenseYear : expenseStart || expenseEnd ? 'the selected date range' : 'all expenses'
    if (!window.confirm(`Delete ${filteredExpenses.length} transaction${filteredExpenses.length === 1 ? '' : 's'} for ${scope}? This cannot be undone.`)) return
    const ids = new Set(filteredExpenses.map(item => item.id))
    setExpenses(items => items.filter(item => !ids.has(item.id)))
    setToast(`${filteredExpenses.length} transactions deleted`)
  }
  const addExpense = (event) => {
    event.preventDefault()
    if (!expenseForm.description.trim() || !expenseForm.amount || !expenseForm.paymentMode) return
    if (editingExpense) setExpenses(items => items.map(item => item.id === editingExpense ? { ...expenseForm, amount: Number(expenseForm.amount), id: item.id } : item))
    else setExpenses(items => [{ ...expenseForm, amount: Number(expenseForm.amount), id: Date.now() }, ...items])
    setEditingExpense(null)
    setExpenseForm({ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today })
    setPage('expenses')
  }
  const goExpenseAdd = () => { setEditingExpense(null); setExpenseForm({ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }); setPage('expense-add') }
  const goExpenseEdit = expense => { setEditingExpense(expense.id); setExpenseForm({ description: expense.description, amount: String(expense.amount), paymentMode: expense.paymentMode, date: expense.date }); setPage('expense-add') }
  const goBulkAdd = () => { setBulkExpenses([{ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }]); setPage('expense-bulk') }
  const saveBulkExpenses = event => { event.preventDefault(); const valid = bulkExpenses.filter(item => item.description.trim() && item.amount && item.paymentMode); if (!valid.length) return; setExpenses(items => [...valid.map((item, index) => ({ ...item, amount: Number(item.amount), id: Date.now() + index })), ...items]); setPage('expenses') }
  const importExpensesFromWorkbook = async file => {
    if (!file) return
    try {
      // Keep Excel dates as serial numbers so the calendar day is never shifted by a timezone.
      const workbook = XLSX.read(await file.arrayBuffer(), { type: 'array', cellDates: false })
      const sheet = workbook.Sheets['2026'] || workbook.Sheets[workbook.SheetNames[0]]
      if (!sheet) throw new Error('missing sheet')
      const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: true, defval: null })
      const dateFromCell = value => {
        if (value instanceof Date && !Number.isNaN(value.valueOf())) return dateKey(value)
        if (typeof value === 'number') { const parsed = XLSX.SSF.parse_date_code(value); if (parsed) return `${parsed.y}-${String(parsed.m).padStart(2, '0')}-${String(parsed.d).padStart(2, '0')}` }
        if (typeof value === 'string' && value.trim()) { const parsed = new Date(value); if (!Number.isNaN(parsed.valueOf())) return dateKey(parsed) }
        return null
      }
      const importKey = `${file.name}:${file.size}:${file.lastModified}`
      const imported = []
      for (let month = 0; month < 12; month++) {
        const column = month * 5
        for (let row = 3; row < rows.length; row++) {
          const date = dateFromCell(rows[row]?.[column]); const description = String(rows[row]?.[column + 2] || '').trim(); const amount = Number(rows[row]?.[column + 3])
          if (date && description && Number.isFinite(amount)) imported.push({ date, description, amount, paymentMode: String(rows[row]?.[column + 1] || 'Unspecified').trim() || 'Unspecified', sourceImportKey: importKey })
        }
      }
      if (!imported.length) throw new Error('no transactions')
      const previouslyImported = expenses.filter(item => item.sourceImportKey === importKey)
      if (previouslyImported.length) {
        // Re-importing replaces this file's prior rows, which also repairs timezone-shifted imports.
        const now = Date.now()
        setExpenses(items => [...imported.map((item, index) => ({ ...item, id: now + index })), ...items.filter(item => item.sourceImportKey !== importKey)])
        setToast(`${imported.length} transactions replaced from this workbook`)
        return
      }
      const now = Date.now()
      setExpenses(items => [...imported.map((item, index) => ({ ...item, id: now + index })), ...items])
      setToast(`${imported.length} transactions imported to your account`)
    } catch { setToast('Could not read this Excel file. Please use the 2026 expense workbook format.') }
  }
  const openTodo = task => setTodoEditor(task || { title: '', description: '', priority: 'medium', dueDate: today, dueTime: '', scheduledDates: [], category: '', tags: '', recurrence: 'none', customRecurrence: '' })
  const saveTodo = task => { const now = new Date().toISOString(); const category = String(task.category || '').trim(); if (category) setTodoCategories(items => items.some(item => item.toLowerCase() === category.toLowerCase()) ? items : [...items, category].sort((a, b) => a.localeCompare(b))); if (task.id) { setTodos(items => items.map(item => item.id === task.id ? { ...item, ...task, category, updatedAt: now } : item)); setToast('Task updated') } else { setTodos(items => [{ ...task, category, id: Date.now(), status: 'pending', createdAt: now, updatedAt: now, completedAt: null }, ...items]); setToast('Task added') }; setTodoEditor(null) }
  const toggleTodo = id => setTodos(items => items.map(item => item.id === id ? { ...item, status: item.status === 'completed' ? 'pending' : 'completed', completedAt: item.status === 'completed' ? null : new Date().toISOString(), updatedAt: new Date().toISOString() } : item))
  const duplicateTodo = task => { const now = new Date().toISOString(); setTodos(items => [{ ...task, id: Date.now(), title: `${task.title} (copy)`, status: 'pending', completedAt: null, createdAt: now, updatedAt: now }, ...items]); setToast('Task duplicated') }

  if (firebaseReady && !authChecked) return <div className="auth-loading">Loading your space…</div>
  if (firebaseReady && !user) return <LoginPage error={authError} onLogin={() => signInWithPopup(auth, googleProvider).catch(() => setAuthError('Sign-in was cancelled or could not be completed. Please try again.'))} />

  return <div className="app-shell">
    <aside className="sidebar">
      <button className="brand" onClick={() => setPage('dashboard')}><span className="brand-mark">L</span><span>{appName}</span></button>
      <nav>
        <Nav item="dashboard" label="Overview" page={page} setPage={setPage} />
        <p className="nav-group">HABIT MANAGER</p>
        <Nav item="habits" label="My habits" page={page} setPage={setPage} />
        <Nav item="stats" label="Stats" page={page} setPage={setPage} />
        <Nav item="history" label="History" page={page} setPage={setPage} />
        <p className="nav-group">EXPENSE MANAGER</p>
        <Nav item="expenses" label="Expenses" page={page} setPage={setPage} />
        <Nav item="history" label="Expense history" page={page} setPage={setPage} expense />
        <Nav item="stats" label="Expense stats" page={page} setPage={setPage} expense />
        <Nav item="payments" label="Payment modes" page={page} setPage={setPage} />
        <p className="nav-group">TODO MANAGER</p>
        <Nav item="todos" label="My tasks" page={page} setPage={setPage} />
        <p className="nav-group">WELLNESS</p>
        <Nav item="wellness" label="Diet & workout" page={page} setPage={setPage} />
      </nav>
      <div className="sidebar-bottom"><Nav item="settings" label="Settings" page={page} setPage={setPage} /><Profile user={user} /></div>
    </aside>
    <main>
      <header className="topbar"><button className="mobile-menu-toggle" onClick={() => setMobileNavOpen(value => !value)} aria-label="Open navigation" aria-expanded={mobileNavOpen}>☰</button><button className="mobile-logo brand" onClick={() => setPage('dashboard')}><span className="brand-mark">L</span><span>{appName}</span></button><div className="today">{dateLabel}</div><div className="header-actions"><CloudStatus user={user} error={authError} />{page !== 'wellness' && page !== 'dashboard' && <button className="add-button" onClick={page === 'todos' ? () => openTodo() : page.startsWith('expense') || page === 'expenses' || page === 'payments' ? goExpenseAdd : goAdd}><b>+</b> Add {page === 'todos' ? 'task' : page.startsWith('expense') || page === 'expenses' || page === 'payments' ? 'expense' : 'habit'}</button>}</div></header>
      {page === 'dashboard' && <Dashboard habits={habits} expenses={expenses} todos={todos} plans={plans} bodyWeights={bodyWeights} stats={stats} onToggleDate={toggleDate} onAdd={goAdd} onEdit={goEdit} onDelete={deleteHabit} setPage={setPage} />}
      {page === 'habits' && <Habits habits={shownHabits} filter={filter} setFilter={setFilter} onToggle={toggle} onToggleDate={toggleDate} onAdd={goAdd} onEdit={goEdit} menuOpen={menuOpen} setMenuOpen={setMenuOpen} onDelete={deleteHabit} />}
      {page === 'add' && <HabitForm form={form} setForm={setForm} onSave={save} onCancel={() => setPage('habits')} editing={!!editing} />}
      {page === 'stats' && <Stats habits={habits} />}
      {page === 'expenses' && <Expenses expenses={filteredExpenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} onAdd={goExpenseAdd} onBulkAdd={goBulkAdd} onImport={importExpensesFromWorkbook} onDeleteFiltered={deleteFilteredExpenses} onEdit={goExpenseEdit} onDelete={id => setExpenses(items => items.filter(item => item.id !== id))} />}
      {page === 'expense-add' && <ExpenseForm form={expenseForm} setForm={setExpenseForm} paymentModes={paymentModes} onSave={addExpense} onCancel={() => setPage('expenses')} editing={!!editingExpense} />}
      {page === 'expense-bulk' && <BulkExpenseForm rows={bulkExpenses} setRows={setBulkExpenses} paymentModes={paymentModes} onSave={saveBulkExpenses} onCancel={() => setPage('expenses')} />}
      {page === 'expense-stats' && <ExpenseStats expenses={filteredExpenses} allExpenses={expenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} />}
      {page === 'expense-history' && <ExpenseHistory expenses={filteredExpenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} />}
      {page === 'payments' && <PaymentModes modes={paymentModes} setModes={setPaymentModes} />}
      {page === 'todos' && <TodoManager tasks={todos} prefs={todoPrefs} setPrefs={setTodoPrefs} onAdd={() => openTodo()} onEdit={openTodo} onToggle={id => { toggleTodo(id); const task = todos.find(item => item.id === id); setToast(task?.status === 'completed' ? 'Task marked incomplete' : 'Task completed') }} onDuplicate={duplicateTodo} onDelete={task => setTodoConfirm(task)} />}
      {page === 'wellness' && <WellnessManager plans={plans} setPlans={setPlans} weights={bodyWeights} setWeights={setBodyWeights} notify={setToast} />}
      {page === 'history' && <History habits={habits} />}
      {page === 'settings' && <section className="page simple-page"><p className="eyebrow">PREFERENCES</p><h1>Settings</h1><p>Your habits are stored securely in this browser.</p></section>}
      <footer className="site-footer">Conceptualized and developed by <a href="https://www.linkedin.com/in/pulkit-singh-80a66917a/" target="_blank" rel="noreferrer">Pulkit Singh <span aria-hidden="true">↗</span></a></footer>
    </main>
    <MobileNav page={page} setPage={setPage} open={mobileNavOpen} close={() => setMobileNavOpen(false)} user={user} />
    {page !== 'wellness' && page !== 'dashboard' && <button className="floating-add" onClick={page === 'todos' ? () => openTodo() : page.startsWith('expense') || page === 'expenses' || page === 'payments' ? goExpenseAdd : goAdd}>+</button>}
    {todoEditor && <TodoEditor task={todoEditor} categories={todoCategories} onSave={saveTodo} onClose={() => setTodoEditor(null)} />}
    {todoConfirm && <ConfirmDialog task={todoConfirm} onCancel={() => setTodoConfirm(null)} onConfirm={() => { setTodos(items => items.filter(item => item.id !== todoConfirm.id)); setTodoConfirm(null); setToast('Task deleted') }} />}
    {toast && <div className="toast" role="status">✓ {toast}</div>}
  </div>
}

function CloudStatus({ user, error }) {
  if (!firebaseReady) return <span className="cloud-status local">Local only</span>
  if (user) return <button className="account-button" title="Sign out" onClick={() => signOut(auth)}>{user.photoURL ? <img src={user.photoURL} alt="" /> : null}<span>Log out</span></button>
  return null
}

function LoginPage({ onLogin, error }) {
  return <main className="login-page"><section className="login-panel"><button className="brand login-brand"><span className="brand-mark">L</span><span>LevelUp</span></button><div className="login-copy"><p className="eyebrow">YOUR PERSONAL RITUAL SPACE</p><h1>Small steps,<br /><em>every day.</em></h1><p>Build a life you’re proud of, one deliberate choice at a time.</p></div><div className="login-feature"><span>✦</span><p>Your data stay safely in sync across every device.</p></div></section><section className="login-form"><div className="login-card"><p className="eyebrow">WELCOME TO LEVELUP</p><h2>Make today count.</h2><p>Sign in to access your rituals and keep your streak going wherever you are.</p><button className="google-login" onClick={onLogin}><b>G</b> Continue with Google</button>{error && <p className="login-error">{error}</p>}<small>By continuing, you agree to keep showing up for yourself.</small></div></section></main>
}

function Nav({ item, label, page, setPage, expense }) { const destination = expense ? (item === 'history' ? 'expense-history' : 'expense-stats') : item; return <button className={`nav-item ${page === destination ? 'active' : ''}`} onClick={() => setPage(destination)}><span>{icons[item]}</span>{label}</button> }
function MobileNav({ page, setPage, open, close, user }) {
  const select = destination => { setPage(destination); close() }
  return <div className={`mobile-nav ${open ? 'open' : ''}`} aria-hidden={!open}><button className="mobile-nav-backdrop" onClick={close} aria-label="Close navigation" /><nav className="mobile-nav-drawer" aria-label="Main navigation"><button className="mobile-nav-close" onClick={close}>×</button><p className="nav-group">MAIN</p><Nav item="dashboard" label="Overview" page={page} setPage={select} /><p className="nav-group">HABIT MANAGER</p><Nav item="habits" label="My habits" page={page} setPage={select} /><Nav item="stats" label="Stats" page={page} setPage={select} /><Nav item="history" label="History" page={page} setPage={select} /><p className="nav-group">EXPENSE MANAGER</p><Nav item="expenses" label="Expenses" page={page} setPage={select} /><Nav item="history" label="Expense history" page={page} setPage={select} expense /><Nav item="stats" label="Expense stats" page={page} setPage={select} expense /><Nav item="payments" label="Payment modes" page={page} setPage={select} /><p className="nav-group">TODO MANAGER</p><Nav item="todos" label="My tasks" page={page} setPage={select} /><p className="nav-group">WELLNESS</p><Nav item="wellness" label="Diet & workout" page={page} setPage={select} /><div className="mobile-nav-account"><Nav item="settings" label="Settings" page={page} setPage={select} /><Profile user={user} /></div></nav></div>
}

const priorityRank = { high: 0, medium: 1, low: 2 }
const startOfDay = value => { const d = new Date(`${value}T00:00:00`); d.setHours(0, 0, 0, 0); return d }
// A due date and added schedule dates are both valid task dates. Previously, a
// scheduled date could hide the main due date from month and view filtering.
const taskDates = task => [...new Set([task.dueDate, ...(task.scheduledDates || [])].filter(Boolean))]
const relativeDue = task => { const date = taskDates(task).sort()[0]; if (!date) return 'No due date'; const diff = Math.round((startOfDay(date) - startOfDay(today)) / 86400000); if (diff < 0) return `${Math.abs(diff)}d overdue`; if (!diff) return task.dueTime ? `Today · ${task.dueTime}` : 'Today'; if (diff === 1) return 'Tomorrow'; return new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(startOfDay(date)) }

function TodoManager({ tasks, prefs, setPrefs, onAdd, onEdit, onToggle, onDuplicate, onDelete }) {
  const [search, setSearch] = useState('')
  const filters = [['all', 'All Tasks'], ['pending', 'Pending'], ['completed', 'Completed'], ['high', 'High Priority'], ['medium', 'Medium Priority'], ['low', 'Low Priority'], ['today', 'Today'], ['tomorrow', 'Tomorrow'], ['week', 'This Week'], ['month', 'This Month'], ['overdue', 'Overdue']]
  const taskMonths = [...new Set(tasks.flatMap(task => {
    const dates = taskDates(task)
    return (dates.length ? dates : [task.createdAt?.slice(0, 10)]).filter(Boolean).map(date => date.slice(0, 7))
  }))].sort().reverse()
  const monthLabel = month => new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(startOfDay(`${month}-01`))
  const filterTask = task => {
    const term = search.toLowerCase(); if (term && !`${task.title} ${task.description}`.toLowerCase().includes(term)) return false
    const dates = taskDates(task)
    const months = (dates.length ? dates : [task.createdAt?.slice(0, 10)]).filter(Boolean).map(date => date.slice(0, 7))
    if (prefs.month !== 'all' && !months.includes(prefs.month)) return false
    if (prefs.filter === 'all') return true
    if (['pending', 'completed'].includes(prefs.filter)) return task.status === prefs.filter
    if (['high', 'medium', 'low'].includes(prefs.filter)) return task.priority === prefs.filter
    if (!dates.length) return false
    const diffs = dates.map(date => Math.floor((startOfDay(date) - startOfDay(today)) / 86400000))
    if (prefs.filter === 'today') return diffs.includes(0)
    if (prefs.filter === 'tomorrow') return diffs.includes(1)
    if (prefs.filter === 'week') return diffs.some(diff => diff >= 0 && diff <= 6)
    if (prefs.filter === 'month') return dates.some(date => date.slice(0, 7) === today.slice(0, 7))
    return diffs.some(diff => diff < 0) && task.status !== 'completed'
  }
  const shown = tasks.filter(filterTask).sort((a, b) => {
    if (prefs.sort === 'priority') return priorityRank[a.priority] - priorityRank[b.priority]
    if (prefs.sort === 'alphabetical') return a.title.localeCompare(b.title)
    if (prefs.sort === 'created') return new Date(b.createdAt) - new Date(a.createdAt)
    if (prefs.sort === 'updated') return new Date(b.updatedAt) - new Date(a.updatedAt)
    return (taskDates(a).sort()[0] || '9999').localeCompare(taskDates(b).sort()[0] || '9999') || (a.dueTime || '').localeCompare(b.dueTime || '')
  })
  const viewTasks = shown.filter(task => {
    const dates = taskDates(task)
    if (!dates.length) return false
    if (prefs.view === 'calendar') return true
    if (prefs.view === 'daily') return dates.includes(today)
    if (prefs.view === 'weekly') {
      const weekStart = new Date(); weekStart.setHours(0, 0, 0, 0); weekStart.setDate(weekStart.getDate() - weekStart.getDay())
      const weekEnd = new Date(weekStart); weekEnd.setDate(weekEnd.getDate() + 7)
      return dates.some(date => startOfDay(date) >= weekStart && startOfDay(date) < weekEnd)
    }
    if (prefs.view === 'monthly') return dates.some(date => date.slice(0, 7) === (prefs.month !== 'all' ? prefs.month : today.slice(0, 7)))
    return dates.some(date => date.slice(0, 4) === today.slice(0, 4))
  })
  const completed = tasks.filter(task => task.status === 'completed'); const todayDone = completed.filter(task => task.completedAt?.slice(0, 10) === today).length
  const weekDone = completed.filter(task => task.completedAt && Math.floor((Date.now() - new Date(task.completedAt)) / 86400000) < 7).length
  const monthDone = completed.filter(task => task.completedAt?.slice(0, 7) === today.slice(0, 7)).length
  const dates = new Set(completed.map(task => task.completedAt?.slice(0, 10)).filter(Boolean)); let streak = 0; for (let d = new Date(); dates.has(dateKey(d)); d.setDate(d.getDate() - 1)) streak++; const completedDays = [...dates].sort(); let longest = 0; let run = 0; let previous = null; completedDays.forEach(day => { if (previous && Math.round((startOfDay(day) - startOfDay(previous)) / 86400000) === 1) run++; else run = 1; longest = Math.max(longest, run); previous = day })
  const calendarTasks = [...viewTasks].sort((a, b) => (taskDates(a).sort()[0]).localeCompare(taskDates(b).sort()[0]))
  return <section className="page todo-page"><div className="todo-heading"><div><p className="eyebrow">TODO MANAGER</p><h1>Plan with <em>purpose.</em></h1><p className="subcopy">{tasks.length} tasks · {tasks.filter(t => t.status === 'pending').length} still in motion</p></div><button className="save" onClick={onAdd}>+ New task</button></div>
    <div className="todo-stats"><TodoStat label="Total Tasks" value={tasks.length} /><TodoStat label="Completed" value={completed.length} /><TodoStat label="Pending" value={tasks.length - completed.length} /><TodoStat label="Completion" value={`${tasks.length ? Math.round(completed.length / tasks.length * 100) : 0}%`} /><TodoStat label="Today" value={todayDone} /><TodoStat label="Weekly" value={weekDone} /><TodoStat label="Monthly" value={monthDone} /><TodoStat label="Current Streak" value={`${streak}d`} /><TodoStat label="Longest Streak" value={`${longest}d`} /></div>
    <div className="todo-toolbar"><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search title or description…" aria-label="Search tasks" /><select value={prefs.month} onChange={e => setPrefs(p => ({ ...p, month: e.target.value, view: e.target.value === 'all' ? 'calendar' : 'monthly', filter: ['today', 'tomorrow', 'week', 'month', 'overdue'].includes(p.filter) ? 'all' : p.filter }))} aria-label="Filter tasks by month"><option value="all">All months</option>{taskMonths.map(month => <option key={month} value={month}>{monthLabel(month)}</option>)}</select><select value={prefs.sort} onChange={e => setPrefs(p => ({ ...p, sort: e.target.value }))}><option value="due">Due Date</option><option value="created">Created Date</option><option value="priority">Priority</option><option value="alphabetical">Alphabetical</option><option value="updated">Recently Updated</option></select><div className="view-switch">{['daily', 'weekly', 'monthly', 'yearly', 'calendar'].map(view => <button key={view} className={prefs.view === view ? 'selected' : ''} onClick={() => setPrefs(p => ({ ...p, view, filter: ['today', 'tomorrow', 'week', 'month', 'overdue'].includes(p.filter) ? 'all' : p.filter }))}>{view}</button>)}</div></div>
    <div className="todo-filters">{filters.map(([id, label]) => <button key={id} className={prefs.filter === id ? 'selected' : ''} onClick={() => setPrefs(p => ({ ...p, filter: id }))}>{label}</button>)}</div>
    {prefs.view === 'calendar' ? <div className="todo-calendar">{calendarTasks.length ? calendarTasks.map(task => <TaskCard key={task.id} task={task} onToggle={onToggle} onEdit={onEdit} onDuplicate={onDuplicate} onDelete={onDelete} calendar />) : <EmptyTasks onAdd={onAdd} />}</div> : <div className="todo-list">{viewTasks.length ? viewTasks.map(task => <TaskCard key={task.id} task={task} onToggle={onToggle} onEdit={onEdit} onDuplicate={onDuplicate} onDelete={onDelete} />) : <EmptyTasks onAdd={onAdd} />}</div>}
  </section>
}
function TodoStat({ label, value }) { return <article><strong>{value}</strong><span>{label}</span></article> }
function EmptyTasks({ onAdd }) { return <button className="empty todo-empty" onClick={onAdd}>No tasks found. Add a task to get moving.</button> }
function TaskCard({ task, onToggle, onEdit, onDuplicate, onDelete, calendar }) { const scheduled = taskDates(task); return <article className={`task-card ${task.status === 'completed' ? 'done' : ''} ${calendar ? 'calendar-task' : ''}`}><button className="task-check" onClick={() => onToggle(task.id)} aria-label={task.status === 'completed' ? 'Mark incomplete' : 'Mark complete'}>{task.status === 'completed' ? '✓' : ''}</button><div className="task-main"><div className="task-title-row"><h3>{task.title}</h3><span className={`priority ${task.priority}`}>{task.priority}</span></div>{task.description && <p>{task.description}</p>}<div className="task-meta"><span className={scheduled.some(date => date < today) && task.status !== 'completed' ? 'overdue' : ''}>{relativeDue(task)}</span>{scheduled.length > 1 && <span>Scheduled: {scheduled.map(date => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(startOfDay(date))).join(', ')}</span>}{task.category && <span>{task.category}</span>}{task.tags?.split(',').filter(Boolean).map(tag => <span key={tag}>#{tag.trim()}</span>)}{task.recurrence !== 'none' && <span>↻ {task.recurrence === 'custom' ? task.customRecurrence || 'custom' : task.recurrence}</span>}{task.completedAt && <span>Completed {new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(task.completedAt))}</span>}</div></div><div className="task-actions"><button onClick={() => onEdit(task)}>Edit</button><button onClick={() => onDuplicate(task)}>Duplicate</button><button className="danger" onClick={() => onDelete(task)}>Delete</button></div></article> }
function TodoEditor({ task, categories, onSave, onClose }) { const [form, setForm] = useState({ ...task, category: task.category || '', scheduledDates: task.scheduledDates || [] }); const [scheduleDate, setScheduleDate] = useState(task.dueDate || today); const update = (key, value) => setForm(f => ({ ...f, [key]: value })); const addDate = () => { if (!scheduleDate) return; const dates = [...new Set([...form.scheduledDates, scheduleDate])].sort(); setForm(f => ({ ...f, scheduledDates: dates, dueDate: dates[0] })); }; const removeDate = date => { const dates = form.scheduledDates.filter(item => item !== date); setForm(f => ({ ...f, scheduledDates: dates, dueDate: dates[0] || f.dueDate })) }; return <div className="modal-backdrop" role="dialog" aria-modal="true"><form className="todo-editor" onSubmit={e => { e.preventDefault(); if (form.title.trim()) onSave({ ...form, title: form.title.trim() }) }}><div className="modal-head"><div><p className="eyebrow">{task.id ? 'EDIT TASK' : 'NEW TASK'}</p><h2>{task.id ? 'Make a change' : 'What needs doing?'}</h2></div><button type="button" onClick={onClose}>×</button></div><label>Title<input autoFocus required value={form.title} onChange={e => update('title', e.target.value)} placeholder="Task title" /></label><label>Description<textarea value={form.description} onChange={e => update('description', e.target.value)} placeholder="Add a little context…" /></label><div className="form-grid"><label>Priority<select value={form.priority} onChange={e => update('priority', e.target.value)}><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><label>Category<input list="todo-categories" value={form.category} onChange={e => update('category', e.target.value)} placeholder="Work, Personal…" /><datalist id="todo-categories">{categories.map(category => <option key={category} value={category} />)}</datalist><small>Enter a new category or choose one you used before.</small></label><label>Due date<input type="date" value={form.dueDate} onChange={e => update('dueDate', e.target.value)} /></label><label>Due time<input type="time" value={form.dueTime} onChange={e => update('dueTime', e.target.value)} /></label></div><div className="schedule-picker"><div><b>Specific task dates</b><small>Add each day this task should appear, such as 27, 29 and 31.</small></div><div className="schedule-add"><input type="date" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} /><button type="button" onClick={addDate}>+ Add date</button></div>{form.scheduledDates.length > 0 && <div className="date-chips">{form.scheduledDates.map(date => <button type="button" key={date} onClick={() => removeDate(date)}>{new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(startOfDay(date))} ×</button>)}</div>}</div><label>Tags <small>Separate tags with commas</small><input value={form.tags} onChange={e => update('tags', e.target.value)} placeholder="focus, home" /></label><div className="form-grid"><label>Repeat<select value={form.recurrence} onChange={e => update('recurrence', e.target.value)}><option value="none">Does not repeat</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="custom">Custom</option></select></label>{form.recurrence === 'custom' && <label>Custom schedule<input value={form.customRecurrence} onChange={e => update('customRecurrence', e.target.value)} placeholder="e.g. Every 3 days" /></label>}</div><div className="modal-actions"><button type="button" className="cancel" onClick={onClose}>Cancel</button><button className="save">{task.id ? 'Save changes' : 'Add task'}</button></div></form></div> }
function ConfirmDialog({ task, onCancel, onConfirm }) { return <div className="modal-backdrop"><section className="confirm-dialog"><p className="eyebrow">DELETE TASK</p><h2>Delete “{task.title}”?</h2><p>This can’t be undone.</p><div className="modal-actions"><button className="cancel" onClick={onCancel}>Cancel</button><button className="delete-button" onClick={onConfirm}>Delete task</button></div></section></div> }
function WellnessManager({ plans, setPlans, weights, setWeights, notify }) {
  const [weight, setWeight] = useState(''); const [date, setDate] = useState(today); const sorted = [...weights].sort((a, b) => b.date.localeCompare(a.date)); const latest = sorted[0]; const oldest = sorted[sorted.length - 1]; const change = latest && oldest && latest.id !== oldest.id ? Number(latest.value) - Number(oldest.value) : 0
  const upload = (type, file) => { if (!file) return; const allowed = ['application/pdf', 'image/jpeg', 'image/png', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']; if (!allowed.includes(file.type)) { notify('Use PDF, JPG, PNG, XLS, or XLSX files'); return } if (file.size > 3500000) { notify('Please choose a file smaller than 3.5 MB'); return } const reader = new FileReader(); reader.onload = () => { setPlans(current => ({ ...current, [type]: { name: file.name, data: reader.result, mimeType: file.type, uploadedAt: new Date().toISOString() } })); notify(`${type === 'diet' ? 'Diet' : type === 'workout' ? 'Workout' : 'Schedule'} file saved in this browser`) }; reader.readAsDataURL(file) }
  const removePlan = type => { setPlans(current => ({ ...current, [type]: null })); notify(`${type === 'diet' ? 'Diet' : type === 'workout' ? 'Workout' : 'Schedule'} file removed`) }
  const saveWeight = event => { event.preventDefault(); const value = Number(weight); if (!value || value < 20 || value > 400) return; setWeights(items => [{ id: items.find(item => item.date === date)?.id || Date.now(), date, value }, ...items.filter(item => item.date !== date)]); setWeight(''); notify('Body weight saved') }
  return <section className="page wellness-page"><p className="eyebrow">WELLNESS MANAGER</p><h1>Fuel. Train. <em>Progress.</em></h1><p className="subcopy">Keep your plans close and see your body-weight trend over time.</p><div className="wellness-summary"><WellnessStat value={latest ? `${latest.value} kg` : '—'} label="Latest weight" /><WellnessStat value={weights.length} label="Weight entries" /><WellnessStat value={latest && oldest && latest.id !== oldest.id ? `${change > 0 ? '+' : ''}${change.toFixed(1)} kg` : '—'} label="Since first entry" /></div><div className="plan-grid"><PlanCard type="diet" plan={plans.diet} onUpload={upload} onRemove={() => removePlan('diet')} /><PlanCard type="workout" plan={plans.workout} onUpload={upload} onRemove={() => removePlan('workout')} /><PlanCard type="schedule" plan={plans.schedule} onUpload={upload} onRemove={() => removePlan('schedule')} /></div><div className="weight-layout"><section className="weight-entry"><p className="eyebrow">DAILY CHECK-IN</p><h2>Log body weight</h2><p>One entry per day. Updating a day replaces its previous value.</p><form onSubmit={saveWeight}><label>Date<input type="date" max={today} value={date} onChange={e => setDate(e.target.value)} /></label><label>Weight (kg)<input type="number" required min="20" max="400" step="0.1" value={weight} onChange={e => setWeight(e.target.value)} placeholder="e.g. 72.4" /></label><button className="save">Save weight</button></form></section><section className="weight-history"><div className="section-heading"><div><p className="eyebrow">BODY WEIGHT</p><h2>Your progress</h2></div>{latest && <strong>{latest.value} kg</strong>}</div><WeightChart weights={weights} />{sorted.length ? <div className="weight-list">{sorted.slice(0, 7).map(entry => <div key={entry.id}><span>{new Intl.DateTimeFormat('en-US', { weekday: 'short', month: 'short', day: 'numeric' }).format(startOfDay(entry.date))}</span><b>{entry.value} kg</b><button onClick={() => { setWeights(items => items.filter(item => item.id !== entry.id)); notify('Weight entry deleted') }}>×</button></div>)}</div> : <p className="no-stats">Your first check-in will appear here.</p>}</section></div></section>
}
function WellnessStat({ value, label }) { return <article><strong>{value}</strong><span>{label}</span></article> }
function PlanCard({ type, plan, onUpload, onRemove }) {
  const inputId = `${type}-file`
  const heading = type === 'diet' ? 'Diet guide' : type === 'workout' ? 'Workout guide' : 'Schedule'
  const source = plan?.data
  const fileKind = plan?.mimeType?.startsWith('image/') ? 'image' : plan?.mimeType?.includes('sheet') || plan?.mimeType === 'application/vnd.ms-excel' ? 'spreadsheet' : 'pdf'
  const openFile = () => { if (source) window.open(source, '_blank', 'noopener,noreferrer') }
  return <section className="plan-card"><div className="section-heading"><div><p className="eyebrow">{type.toUpperCase()}</p><h2>{heading}</h2></div>{plan && <button className="text-button danger-text" onClick={onRemove}>Remove</button>}</div>{plan ? <><p className="plan-file">{fileKind.toUpperCase()} · {plan.name}</p><button className="plan-preview-button" onClick={openFile} aria-label={`Open ${plan.name} in a new tab`}>{fileKind === 'image' ? <img className="plan-preview plan-image" src={source} alt={`${type} preview`} /> : <div className="file-preview">{fileKind === 'spreadsheet' ? '▦ Excel file' : <iframe className="plan-preview" src={source} title={`${type} preview`} tabIndex="-1" />}</div>}<span>Open in new tab ↗</span></button><label className="replace-plan" htmlFor={inputId}>Replace file<input id={inputId} type="file" accept="application/pdf,image/jpeg,image/png,.xls,.xlsx" onChange={e => onUpload(type, e.target.files[0])} /></label></> : <label className="plan-upload" htmlFor={inputId}><span>↑</span><b>Upload your {type}</b><small>PDF, JPG, PNG, XLS, XLSX · Up to 3.5 MB</small><input id={inputId} type="file" accept="application/pdf,image/jpeg,image/png,.xls,.xlsx" onChange={e => onUpload(type, e.target.files[0])} /></label>}</section>
}
function WeightChart({ weights }) { const latest = [...weights].sort((a, b) => a.date.localeCompare(b.date)).slice(-14); if (latest.length < 2) return <div className="weight-chart empty-chart">Add at least two entries to see your trend.</div>; const values = latest.map(entry => Number(entry.value)); const min = Math.min(...values); const max = Math.max(...values); const range = max - min || 1; return <div className="weight-chart">{latest.map(entry => <div key={entry.id}><i style={{ height: `${20 + ((Number(entry.value) - min) / range) * 80}%` }} title={`${entry.date}: ${entry.value} kg`} /><small>{entry.date.slice(5)}</small></div>)}</div> }
function Profile({ user }) { const name = user?.displayName || 'Your habit space'; const initial = name.charAt(0).toUpperCase(); return <div className="profile">{user?.photoURL ? <img className="avatar" src={user.photoURL} alt="" referrerPolicy="no-referrer" /> : <div className="avatar">{initial}</div>}<div><strong>{name}</strong><small>{user?.email || 'Make it count.'}</small></div><span>⌄</span></div> }

function Dashboard({ habits, expenses, todos, plans, bodyWeights, stats, onToggleDate, onAdd, onEdit, onDelete, setPage }) {
  const [showMoney, setShowMoney] = useState(false)
  const monthKey = today.slice(0, 7)
  const todaySpent = expenses.filter(item => item.date === today).reduce((sum, item) => sum + item.amount, 0)
  const monthSpent = expenses.filter(item => item.date.startsWith(monthKey)).reduce((sum, item) => sum + item.amount, 0)
  const recentExpenses = [...expenses].sort((a, b) => b.date.localeCompare(a.date) || b.id - a.id).slice(0, 3)
  const latestWeight = [...bodyWeights].sort((a, b) => b.date.localeCompare(a.date))[0]
  const money = amount => `₹${amount.toLocaleString('en-IN', { maximumFractionDigits: 0 })}`
  return <section className="page overview-page"><div className="headline"><div><p className="eyebrow">YOUR DAILY OVERVIEW</p><h1>Everything that <em>matters.</em></h1><p className="subcopy">A single view of your routines and spending.</p></div><div className="day-progress"><div className="progress-ring" style={{ '--progress': `${stats.total ? (stats.done / stats.total) * 100 : 0}%` }}><span>{stats.done}<small>/{stats.total}</small></span></div><p>habits completed</p></div></div>
    <section className="stat-grid overview-stats"><Stat value={`${stats.done}/${stats.total}`} label="Habits today" icon="✓" onClick={() => setPage('habits')} /><Stat value={`${todos.filter(task => task.status === 'completed').length}/${todos.length}`} label="Tasks completed" icon="☑" onClick={() => setPage('todos')} /><Stat value={latestWeight ? `${latestWeight.value} kg` : '—'} label="Latest body weight" icon="◉" onClick={() => setPage('wellness')} /><Stat value={`${[plans.diet, plans.workout, plans.schedule].filter(Boolean).length}/3`} label="Wellness files" icon="⌁" onClick={() => setPage('wellness')} /><PrivateStat value={showMoney ? money(todaySpent) : '••••'} label="Spent today" onToggle={() => setShowMoney(value => !value)} visible={showMoney} onClick={() => setPage('expenses')} /><PrivateStat value={showMoney ? money(monthSpent) : '••••'} label="Spent this month" onToggle={() => setShowMoney(value => !value)} visible={showMoney} onClick={() => setPage('expenses')} /></section>
    <div className="overview-grid"><section className="overview-panel"><div className="section-heading"><div><p className="eyebrow">HABIT MANAGER</p><h2>Keep your rhythm</h2><p>{stats.best ? `${stats.best}-day best streak · ${habits.length} active habits` : 'Create a routine that works for you.'}</p></div><button className="text-button" onClick={() => setPage('habits')}>View habits →</button></div><WeekTracker habits={habits} onToggleDate={onToggleDate} onAdd={onAdd} onEdit={onEdit} onDelete={onDelete} /></section><section className="overview-panel expense-overview"><div className="section-heading"><div><p className="eyebrow">EXPENSE MANAGER</p><h2>Recent spending</h2><p>{expenses.length ? `${expenses.length} recorded transactions` : 'Start tracking where your money goes.'}</p></div><button className="text-button" onClick={() => setPage('expenses')}>View expenses →</button></div><button className="money-toggle" onClick={() => setShowMoney(value => !value)} aria-pressed={showMoney}>{showMoney ? '◉ Hide amounts' : '◌ View amounts'}</button><div className="overview-expenses">{recentExpenses.length ? recentExpenses.map(item => <article key={item.id}><div><strong>{item.description}</strong><small>{item.paymentMode} · {new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short' }).format(new Date(`${item.date}T00:00:00`))}</small></div><b>{showMoney ? money(item.amount) : '••••'}</b></article>) : <button className="empty" onClick={() => setPage('expense-add')}>+ Add your first expense</button>}</div><button className="overview-add-expense" onClick={() => setPage('expense-add')}>+ Add expense</button></section></div>
  </section>
}
function Stat({ value, label, icon, onClick }) { return <button className="stat-card stat-link" onClick={onClick}><span className="stat-icon">{icon}</span><strong>{value}</strong><p>{label}</p></button> }
function PrivateStat({ value, label, onToggle, visible, onClick }) { return <article className="stat-card private-stat" onClick={onClick}><button onClick={event => { event.stopPropagation(); onToggle() }} aria-label={`${visible ? 'Hide' : 'Show'} ${label}`} title={`${visible ? 'Hide' : 'Show'} amount`}>{visible ? '🙈' : '👁'}</button><strong>{value}</strong><p>{label}</p></article> }
function HabitSection({ label, title, description, habits, accent, onToggle, onAdd, onEdit, menuOpen, setMenuOpen, onDelete }) { return <section className="habit-section"><div className="section-heading"><div><p className={`eyebrow ${accent}`}>{label}</p><h2>{title}</h2><p>{description}</p></div><button className="text-button" onClick={onAdd}>+ Add</button></div><div className="habit-list">{habits.length ? habits.map(h => <HabitCard key={h.id} habit={h} onToggle={onToggle} onEdit={onEdit} onDelete={onDelete} menuOpen={menuOpen} setMenuOpen={setMenuOpen} />) : <Empty onAdd={onAdd} />}</div></section> }
function WeekTracker({ habits, onToggleDate, onAdd, onEdit, onDelete }) { return <section className="week-tracker"><div className="section-heading"><div><p className="eyebrow">WEEKLY TRACKER</p><h2>Your habit rhythm</h2><p>Today and the next 7 days. Upcoming days are locked until they arrive.</p></div><button className="text-button" onClick={onAdd}>+ Add habit</button></div><div className="tracker-scroll"><div className="tracker-table"><div className="tracker-header"><div>HABIT</div>{weekDays.map(day => <div key={day.key} className={day.key === today ? 'is-today' : ''}><span>{day.weekday}</span><b>{day.day}</b></div>)}<div></div></div>{habits.map(habit => <div className="tracker-row" key={habit.id}><button className="tracker-habit" onClick={() => onEdit(habit)}><i style={{ background: habit.color }}></i><span><strong>{habit.name}</strong><small>{habit.type === 'bad' ? `Stopped ${new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(new Date(`${habit.stoppedAt || habit.createdAt}T00:00:00`))}` : habit.target || habit.note || 'Daily habit'}</small></span></button>{weekDays.map(day => { const startDate = habit.type === 'bad' ? habit.stoppedAt || habit.createdAt : habit.startedAt || habit.createdAt; const available = day.key <= today && day.key >= startDate; const checked = habit.type === 'bad' ? available && habit.history?.[day.key] !== false : available && !!habit.history?.[day.key]; return <button key={day.key} disabled={!available} aria-label={`Toggle ${habit.name} for ${day.key}`} className={`day-check ${checked ? 'checked' : ''} ${habit.type}`} onClick={() => onToggleDate(habit.id, day.key)}>{checked ? '✓' : '×'}</button> })}<div className="tracker-menu"><button onClick={() => onEdit(habit)}>•••</button></div></div>)}{!habits.length && <Empty onAdd={onAdd} />}</div></div><p className="tracker-note"><span>✓</span> You can check or undo today and any past day after the habit start date.</p></section> }
function HabitCard({ habit, onToggle, onEdit, onDelete, menuOpen, setMenuOpen }) { const completed = habit.type === 'bad' ? habit.history?.[today] !== false : today >= (habit.startedAt || habit.createdAt) && !!habit.history?.[today], streak = getStreak(habit); return <article className={`habit-card ${completed ? 'completed' : ''}`} onClick={() => onEdit(habit)}><button className="check" onClick={event => { event.stopPropagation(); onToggle(habit.id) }} aria-label={`Toggle ${habit.name}`}>{completed && '✓'}</button><div className="habit-color" style={{ background: habit.color }}></div><div className="habit-info"><h3>{habit.name}</h3><p>{habit.note || 'A small daily promise'}</p></div><div className="streak"><span>♨</span><strong>{streak}</strong><small>day streak</small></div><div className="card-actions"><button onClick={event => { event.stopPropagation(); setMenuOpen(menuOpen === habit.id ? null : habit.id) }}>{icons.more}</button>{menuOpen === habit.id && <div className="menu"><button onClick={event => { event.stopPropagation(); onEdit(habit) }}>Edit habit</button><button className="danger" onClick={event => { event.stopPropagation(); onDelete(habit.id) }}>Delete habit</button></div>}</div></article> }
function Empty({ onAdd }) { return <button className="empty" onClick={onAdd}>+ Add your first habit</button> }
function Habits({ habits, filter, setFilter, ...props }) { return <section className="page"><p className="eyebrow">YOUR ROUTINE</p><h1>My habits</h1><p className="subcopy">Manage the rituals that shape your days.</p><div className="habit-page-tracker"><WeekTracker habits={habits} onToggleDate={props.onToggleDate} onAdd={props.onAdd} onEdit={props.onEdit} onDelete={props.onDelete} /></div><div className="filters"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>All</button><button className={filter === 'good' ? 'selected' : ''} onClick={() => setFilter('good')}>Good habits</button><button className={filter === 'bad' ? 'selected' : ''} onClick={() => setFilter('bad')}>Bad habits</button></div><div className="habit-list full-list">{habits.length ? habits.map(h => <HabitCard key={h.id} habit={h} {...props} />) : <Empty onAdd={props.onAdd} />}</div></section> }
function HabitForm({ form, setForm, onSave, onCancel, editing }) { return <section className="page form-page"><p className="eyebrow">{editing ? 'REFINE YOUR ROUTINE' : 'START SOMETHING NEW'}</p><h1>{editing ? 'Edit habit' : 'Create a habit'}</h1><p className="subcopy">Keep it clear, small and easy to show up for.</p><form onSubmit={onSave}><label>Habit name<input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="e.g. Drink a glass of water" autoFocus /></label><label>A gentle reminder <input value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} placeholder="What does success look like?" /></label><label>Target group<select value={form.target} onChange={e => setForm({ ...form, target: e.target.value })}><option value="">Choose what this habit supports</option>{targetGroups.map(group => <option key={group} value={group}>{group}</option>)}</select><small>Use groups to see where your effort is going on the Stats page.</small></label><fieldset><legend>What kind of habit is this?</legend><div className="type-options"><button type="button" className={form.type === 'good' ? 'type-selected good-type' : ''} onClick={() => setForm({ ...form, type: 'good', color: '#4fa3ff' })}><span>✦</span><b>Good habit</b><small>Build a routine by checking it off.</small></button><button type="button" className={form.type === 'bad' ? 'type-selected bad-type' : ''} onClick={() => setForm({ ...form, type: 'bad', color: '#ffac7d', stoppedAt: form.stoppedAt || today })}><span>◌</span><b>Bad habit</b><small>Stay clear of it to protect your streak.</small></button></div></fieldset>{form.type === 'good' && <label className="start-date">Start date<input type="date" value={form.startedAt} onChange={e => setForm({ ...form, startedAt: e.target.value })} required /><small>The habit can be checked from this date onward.</small></label>}{form.type === 'bad' && <label className="stop-date">When did you stop?<input type="date" max={today} value={form.stoppedAt} onChange={e => setForm({ ...form, stoppedAt: e.target.value })} required /><small>Your clean streak starts from this date.</small></label>}<div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">{editing ? 'Save changes' : 'Create habit'} →</button></div></form></section> }
function ExpenseForm({ form, setForm, paymentModes, onSave, onCancel, editing }) { return <section className="page form-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>{editing ? 'Edit' : 'Add an'} <em>expense.</em></h1><p className="subcopy">Record every payment in one simple place.</p><form onSubmit={onSave}><label>Expense<input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="e.g. Tea and refreshments" autoFocus /></label><label>Amount<input type="number" min="0" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="0.00" /></label><label>Payment mode<select value={form.paymentMode} onChange={e => setForm({ ...form, paymentMode: e.target.value })} required><option value="">Choose payment mode</option>{paymentModes.map(mode => <option key={mode}>{mode}</option>)}</select></label><label>Date<input type="date" value={form.date} max={today} onChange={e => setForm({ ...form, date: e.target.value })} /></label><div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">{editing ? 'Save changes' : 'Save expense'} →</button></div></form></section> }
function BulkExpenseForm({ rows, setRows, paymentModes, onSave, onCancel }) { const update = (index, field, value) => setRows(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, [field]: value } : item)); const addRow = () => setRows(items => [...items, { description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }]); return <section className="page bulk-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Add multiple <em>expenses.</em></h1><p className="subcopy">Enter several payments at once, then save them together.</p><form onSubmit={onSave}><div className="bulk-table"><div className="bulk-header"><span>Expense</span><span>Amount</span><span>Payment mode</span><span>Date</span><span></span></div>{rows.map((row, index) => <div className="bulk-row" key={index}><input value={row.description} onChange={e => update(index, 'description', e.target.value)} placeholder="Expense" /><input type="number" min="0" step="0.01" value={row.amount} onChange={e => update(index, 'amount', e.target.value)} placeholder="0.00" /><select value={row.paymentMode} onChange={e => update(index, 'paymentMode', e.target.value)}><option value="">Choose</option>{paymentModes.map(mode => <option key={mode}>{mode}</option>)}</select><input type="date" value={row.date} max={today} onChange={e => update(index, 'date', e.target.value)} /><button type="button" onClick={() => setRows(items => items.filter((_, itemIndex) => itemIndex !== index))} disabled={rows.length === 1}>×</button></div>)}</div><button type="button" className="text-button" onClick={addRow}>+ Add another row</button><div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">Save all expenses →</button></div></form></section> }
function ExpenseFilters({ filters }) { return <div className="expense-filters"><label>Month<select value={filters.month} onChange={e => filters.setMonth(e.target.value)}><option value="all">All months</option>{filters.months.map(value => <option key={value} value={value}>{new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(new Date(`${value}-01T00:00:00`))}</option>)}</select></label><label>Year<select value={filters.year} onChange={e => filters.setYear(e.target.value)}><option value="all">All years</option>{filters.years.map(year => <option key={year}>{year}</option>)}</select></label><label>From<input type="date" value={filters.start} onChange={e => filters.setStart(e.target.value)} /></label><label>To<input type="date" value={filters.end} onChange={e => filters.setEnd(e.target.value)} /></label><button type="button" onClick={() => { filters.setMonth('all'); filters.setYear('all'); filters.setStart(''); filters.setEnd('') }}>Clear</button></div> }
function ExpenseDateCard({ date, items, onEdit, onDelete }) { const [open, setOpen] = useState(false); const total = items.reduce((sum, item) => sum + item.amount, 0); const confirmDelete = item => { if (window.confirm(`Delete “${item.description}” (₹${item.amount})? This cannot be undone.`)) onDelete(item.id) }; return <section className={`expense-date ${open ? 'open' : ''}`}><button className="expense-date-heading" onClick={() => setOpen(!open)} aria-expanded={open}><div><span className="date-arrow">{open ? '⌄' : '›'}</span><h2>{new Intl.DateTimeFormat('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${date}T00:00:00`))}</h2></div><span><b>₹{total.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b><small>{items.length} expense{items.length === 1 ? '' : 's'}</small></span></button>{open && items.map(item => <article className="expense-row" key={item.id}><div><strong>{item.description}</strong><small>{item.paymentMode}</small></div><b>₹{item.amount.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b><div className="expense-row-actions"><button onClick={() => onEdit(item)}>Edit</button><button className="delete-expense" onClick={() => confirmDelete(item)}>Delete</button></div></article>)}</section> }
function Expenses({ expenses, filters, onAdd, onBulkAdd, onImport, onDeleteFiltered, onEdit, onDelete }) { const total = expenses.reduce((sum, item) => sum + item.amount, 0); const groups = expenses.reduce((all, item) => { (all[item.date] ||= []).push(item); return all }, {}); const filterActive = filters.month !== 'all' || filters.year !== 'all' || filters.start || filters.end; return <section className="page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Your <em>spending.</em></h1><p className="subcopy">{expenses.length} entries · ₹{total.toLocaleString('en-IN', { maximumFractionDigits: 2 })} recorded</p><div className="expense-actions"><button className="text-button" onClick={onBulkAdd}>+ Add multiple expenses</button><label className="text-button import-expenses">↑ Import Excel<input type="file" accept=".xlsx,.xls" onChange={event => { onImport(event.target.files?.[0]); event.target.value = '' }} /></label></div><ExpenseFilters filters={filters} />{filterActive && expenses.length > 0 && <div className="expense-actions"><button className="text-button delete-filtered" onClick={onDeleteFiltered}>Delete {expenses.length} filtered transaction{expenses.length === 1 ? '' : 's'}</button></div>}<div className="expense-list date-sections">{Object.entries(groups).sort(([a], [b]) => b.localeCompare(a)).map(([date, items]) => <ExpenseDateCard key={date} date={date} items={items} onEdit={onEdit} onDelete={onDelete} />)}{!expenses.length && <button className="empty" onClick={onAdd}>+ Add your first expense</button>}</div></section> }
function ExpenseStats({ expenses, filters }) { const total = expenses.reduce((sum, item) => sum + item.amount, 0); const byMode = Object.values(expenses.reduce((all, item) => { all[item.paymentMode] = all[item.paymentMode] || { name: item.paymentMode, total: 0 }; all[item.paymentMode].total += item.amount; return all }, {})).sort((a, b) => b.total - a.total); return <section className="page stats-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Expense <em>stats.</em></h1><p className="subcopy">Your recorded spending, broken down by payment mode.</p><ExpenseFilters filters={filters} /><div className="stats-summary"><Stat value={`₹${total.toLocaleString('en-IN', { maximumFractionDigits: 0 })}`} label="Total spending" icon="₹" /><Stat value={expenses.length} label="Transactions" icon="▣" /><Stat value={byMode[0]?.name || '—'} label="Most used payment mode" icon="◌" /></div><section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">PAYMENT BREAKDOWN</p><h2>Where you paid</h2></div></div><div className="group-progress">{byMode.length ? byMode.map((mode, index) => { const percent = total ? Math.round(mode.total / total * 100) : 0; return <article key={mode.name}><div><span style={{ background: index % 2 ? '#72b7ff' : '#4fa3ff' }}></span><strong>{mode.name}</strong><b>₹{mode.total.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</b></div><div className="group-track"><i style={{ width: `${percent}%`, background: index % 2 ? '#72b7ff' : '#4fa3ff' }} /></div><small>{percent}% of recorded spending</small></article> }) : <p className="no-stats">No expenses match these filters.</p>}</div></section></section> }
function ExpenseHistory({ expenses, filters }) { const groups = expenses.reduce((all, item) => { const key = item.date.slice(0, 7); (all[key] ||= []).push(item); return all }, {}); return <section className="page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Expense <em>history.</em></h1><p className="subcopy">Your spending, grouped month by month.</p><ExpenseFilters filters={filters} /><div className="expense-history">{Object.entries(groups).sort(([a], [b]) => b.localeCompare(a)).map(([key, items]) => <section key={key} className="history-month"><div><h2>{new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(new Date(`${key}-01T00:00:00`))}</h2><b>₹{items.reduce((sum, item) => sum + item.amount, 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b></div><p>{items.length} transactions</p></section>)}{!Object.keys(groups).length && <p className="no-stats">No expenses match these filters.</p>}</div></section> }
function PaymentModes({ modes, setModes }) { const [newMode, setNewMode] = useState(''); const [dragged, setDragged] = useState(null); const add = event => { event.preventDefault(); const value = newMode.trim(); if (value && !modes.includes(value)) { setModes([...modes, value]); setNewMode('') } }; const move = target => { if (!dragged || dragged === target) return; const next = modes.filter(mode => mode !== dragged); next.splice(next.indexOf(target), 0, dragged); setModes(next); setDragged(null) }; return <section className="page payment-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Payment <em>modes.</em></h1><p className="subcopy">Drag modes to set the order shown when adding an expense.</p><form className="mode-form" onSubmit={add}><input value={newMode} onChange={e => setNewMode(e.target.value)} placeholder="e.g. ICICI UPI" /><button className="save">Add mode</button></form><div className="mode-list">{modes.map(mode => <div key={mode} draggable onDragStart={() => setDragged(mode)} onDragOver={event => event.preventDefault()} onDrop={() => move(mode)} className={dragged === mode ? 'dragging' : ''}><span><i>⠿</i>{mode}</span><button onClick={() => setModes(modes.filter(item => item !== mode))} aria-label={`Delete ${mode}`}>×</button></div>)}</div></section> }
function History({ habits }) { return <section className="page"><p className="eyebrow">LOOKING BACK</p><h1>History</h1><p className="subcopy">A simple record of your consistency.</p><div className="history-grid">{habits.map(h => <article className="history-card" key={h.id}><span style={{ background: h.color }}></span><div><h3>{h.name}</h3><p>{h.type === 'good' ? 'Good habit' : 'Bad habit'}</p></div><strong>{getStreak(h)}<small> day streak</small></strong></article>)}</div></section> }

function Stats({ habits }) {
  const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (6 - index)); return dateKey(date) })
  const isComplete = (habit, date) => habit.type === 'bad'
    ? date >= (habit.stoppedAt || habit.createdAt) && habit.history?.[date] !== false
    : !!habit.history?.[date]
  const daily = days.map(date => { const eligible = habits.filter(h => h.type !== 'bad' || date >= (h.stoppedAt || h.createdAt)); const done = eligible.filter(h => isComplete(h, date)).length; return { date, done, total: eligible.length, percent: eligible.length ? Math.round(done / eligible.length * 100) : 0 } })
  const completed = daily.reduce((sum, day) => sum + day.done, 0)
  const possible = daily.reduce((sum, day) => sum + day.total, 0)
  const consistency = possible ? Math.round(completed / possible * 100) : 0
  const bestDay = [...daily].sort((a, b) => b.percent - a.percent)[0]
  const groups = Object.values(habits.reduce((all, habit) => { const name = habit.target || 'Unassigned'; if (!all[name]) all[name] = { name, done: 0, total: 0, color: habit.color }; days.forEach(date => { if (habit.type !== 'bad' || date >= (habit.stoppedAt || habit.createdAt)) { all[name].total++; if (isComplete(habit, date)) all[name].done++ } }); return all }, {})).sort((a, b) => b.done / Math.max(b.total, 1) - a.done / Math.max(a.total, 1))
  return <section className="page stats-page">
    <p className="eyebrow">YOUR PROGRESS</p><h1>Stats that tell your <em>story.</em></h1><p className="subcopy">A look at your consistency over the last seven days.</p>
    <div className="stats-summary"><Stat value={`${consistency}%`} label="Weekly consistency" icon="◔" /><Stat value={completed} label="Habits completed" icon="✓" /><Stat value={bestDay ? `${bestDay.percent}%` : '—'} label="Best day" icon="✦" /></div>
    <section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">LAST 7 DAYS</p><h2>Daily rhythm</h2></div><strong>{completed}<small> completions</small></strong></div><div className="bar-chart">{daily.map(day => <div className="bar-column" key={day.date}><div className="bar-track"><div className="bar-fill" style={{ height: `${day.percent}%` }} title={`${day.done}/${day.total} completed`} /></div><b>{day.percent}%</b><small>{new Intl.DateTimeFormat('en-US', { weekday: 'short' }).format(new Date(`${day.date}T00:00:00`))}</small></div>)}</div></section>
    <section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">BY TARGET GROUP</p><h2>Where you’re growing</h2><p>Completion rate for each focus area this week.</p></div></div><div className="group-progress">{groups.length ? groups.map(group => {
      const percent = group.total ? Math.round(group.done / group.total * 100) : 0
      return <article key={group.name}><div><span style={{ background: group.color }}></span><strong>{group.name}</strong><b>{percent}%</b></div><div className="group-track"><i style={{ width: `${percent}%`, background: group.color }} /></div><small>{group.done} of {group.total} check-ins completed</small></article>
    }) : <p className="no-stats">Add a habit to start seeing your progress here.</p>}</div></section>
  </section>
}

export default App
